77. impl PhysMemoryManager {
78.     ///
79.     /// # Description
80.     ///
81.     /// Initializes the physical memory manager singleton.
82.     ///
83.     /// # Parameters
84.     ///
85.     /// - `upool`: User page pool.
86.     ///
87.     /// # Errors
88.     ///
89.     /// Returns `InvalidArgument` if the singleton has already been initialized.
90.     ///
91.     #[verus_verify(external_body)]
92.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
93.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
94.             return Err(Error::new(
95.                 ErrorCode::InvalidArgument,
96.                 "physical memory manager already initialized",
97.             ));
98.         }
99. 
100.         // SAFETY: this happens during kernel initialization and no other threads are running.
101.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
102.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
