106.     ///
107.     /// # Description
108.     ///
109.     /// Gets a mutable reference to the physical memory manager.
110.     ///
111.     /// # Panics
112.     ///
113.     /// Panics if the physical memory manager is not initialized.
114.     ///
115.     /// # Safety
116.     ///
117.     /// This function is unsafe because it returns a mutable reference to a global variable.
118.     ///
119.     /// The caller must ensure:
120.     ///
121.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
122.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
123.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
124.     ///   re-entrant or concurrent call can alias the reference.
125.     ///
126.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
127.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
128.             panic!("physical memory manager is not initialized");
129.         }
130. 
131.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
132.         PHYS_MEMORY_MANAGER.assume_init_mut()
133.     }
