135.     ///
136.     /// # Description
137.     ///
138.     /// Allocates user frames into caller-provided storage.
139.     ///
140.     /// The returned frames are not guaranteed to be physically contiguous.
141.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
142.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
143.     ///
144.     /// # Parameters
145.     ///
146.     /// - `count`: Number of frames to allocate.
147.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
148.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
149.     ///
150.     /// # Return Values
151.     ///
152.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
153.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
154.     /// back to empty.
155.     ///
156.     pub fn alloc_many_user_frames(
157.         &mut self,
158.         count: usize,
159.         frames: &mut Vec<UserFrame>,
160.     ) -> Result<(), Error> {
161.         if !frames.is_empty() {
162.             let reason: &str = "frames vector is not empty";
163.             error!("{reason}");
164.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
165.         }
166.         if frames.capacity() < count {
167.             let reason: &str = "frames vector has insufficient capacity";
168.             error!("{reason}");
169.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
170.         }
171. 
172.         // A zero-sized allocation is trivially satisfied.
173.         if count == 0 {
174.             return Ok(());
175.         }
176. 
177.         Self::check_user_watermark(count)?;
178. 
179.         for _ in 0..count {
180.             match self.upool.alloc() {
181.                 Ok(frame) => frames.push(frame),
182.                 Err(error) => {
183.                     frames.clear();
184.                     return Err(error);
185.                 },
186.             }
187.         }
188.         Ok(())
189.     }
