191.     ///
192.     /// # Description
193.     ///
194.     /// Allocates a single user frame, applying the same kernel watermark check as
195.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
196.     /// hot paths such as copy-on-write fault resolution, where allocating an
197.     /// intermediate [`Vec`] would be wasteful.
198.     ///
199.     /// # Returns
200.     ///
201.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
202.     /// instead.
203.     ///
204.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
205.         Self::check_user_watermark(1)?;
206.         self.upool.alloc()
207.     }
208. 
209.     ///
210.     /// # Description
211.     ///
212.     /// Rejects user allocations of `count` frames that would breach the kernel
213.     /// watermark, i.e. that would drop the number of free frames below
214.     /// [`config::kernel::KERNEL_WATERMARK`].
215.     ///
216.     /// # Parameters
217.     ///
218.     /// - `count`: Number of user frames the caller intends to allocate.
219.     ///
220.     /// # Returns
221.     ///
222.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
223.     ///
224.     fn check_user_watermark(count: usize) -> Result<(), Error> {
225.         let watermark_threshold: usize = config::kernel::KERNEL_WATERMARK
226.             .checked_add(count)
227.             .ok_or_else(|| {
228.                 let reason: &str = "watermark + count overflow";
229.                 error!("{reason}");
230.                 Error::new(ErrorCode::InvalidArgument, reason)
231.             })?;
232.         if frame::free_count() < watermark_threshold {
233.             let reason: &str = "would breach kernel watermark";
234.             error!("{reason}");
235.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
236.         }
237.         Ok(())
238.     }
239. 
240.     ///
241.     /// # Description
242.     ///
243.     /// Allocates a kernel frame.
244.     ///
245.     /// Kernel allocations bypass the watermark — no artificial ceiling.
246.     ///
247.     /// # Return Values
248.     ///
249.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
250.     ///
251.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
252.         let frame_addr: FrameAddress = frame::alloc()?;
253.         KernelFrame::new(frame_addr).inspect_err(|e| {
254.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
255.             if let Err(free_err) = frame::free(frame_addr) {
256.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
257.             }
258.         })
259.     }
260. 
261.     ///
262.     /// # Description
263.     ///
264.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
265.     ///
266.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
267.     /// mapping and the hardware stack pointer traverses the region linearly.
268.     /// Kernel allocations bypass the watermark — no artificial ceiling.
269.     ///
270.     /// # Parameters
271.     ///
272.     /// - `count`: Number of frames to allocate.
273.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
274.     ///   those frames' addresses.
275.     ///
276.     /// # Return Values
277.     ///
278.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
279.     /// contiguous entries. Upon failure, an error is returned instead.
280.     ///
281.     pub fn alloc_many_kernel_frames(
282.         &mut self,
283.         count: usize,
284.         frames: &mut Vec<KernelFrame>,
285.     ) -> Result<(), Error> {
286.         // Check if caller-provided vector is not empty.
287.         if !frames.is_empty() {
288.             let reason: &str = "frames vector is not empty";
289.             error!("{reason}");
290.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
291.         }
292.         if frames.capacity() < count {
293.             let reason: &str = "frames vector has insufficient capacity";
294.             error!("{reason}");
295.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
296.         }
297. 
298.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
299.         let base_raw: usize = base_addr.into_raw_value();
300.         for i in 0..count {
301.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
302.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
303.                 Ok(kf) => frames.push(kf),
304.                 Err(e) => {
305.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
306.                     frames.clear();
307.                     // Free remaining un-wrapped frames from the contiguous allocation.
308.                     for j in i..count {
309.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
310.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
311.                             if let Err(e) = frame::free(fa) {
312.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
313.                             }
314.                         }
315.                     }
316.                     return Err(e);
317.                 },
318.             }
319.         }
320.         Ok(())
321.     }
322. }
