 use vstd::prelude::*;
 #[cfg(verus_keep_ghost)]
 include!("manager.spec.rs");
 #[cfg(verus_keep_ghost)]
 include!("manager.proof.rs");

 use crate::{
     hal::mem::FrameAddress,
     mm::phys::{
         frame,
         kframe::KernelFrame,
         upool::{
             Upool,
             UserFrame,
         },
